import{H as e,_t as t,it as n,rt as r}from"./chunks/framework.Bcve9O8f.js";var i=JSON.parse(`{"title":"How it folds — a guide","description":"","frontmatter":{"title":"How it folds — a guide","head":[["meta",{"name":"robots","content":"index, follow"}],["meta",{"property":"og:title","content":"How it folds — a guide | Millennium Solutions"}],["meta",{"property":"og:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/folds.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"How it folds — a guide | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/folds.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/folds.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/folds.html"}]]},"headers":[],"relativePath":"folds.md","filePath":"folds.md"}`),a={name:`folds.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="how-it-folds-—-a-guide-for-everyone" tabindex="-1">How it folds — a guide for everyone <a class="header-anchor" href="#how-it-folds-—-a-guide-for-everyone" aria-label="Permalink to “How it folds — a guide for everyone”">​</a></h1><p>For a child or an elder. No jargon needed. A content-address proves integrity, not truth.</p><h2 id="_1-what-a-theorem-is" tabindex="-1">1. What a theorem is <a class="header-anchor" href="#_1-what-a-theorem-is" aria-label="Permalink to “1. What a theorem is”">​</a></h2><p>A <strong>theorem</strong> here is just <strong>a fact you can check yourself</strong>. Not a story someone tells you — something you can re-do and get the same answer, every time. Like <code>2 + 2 = 4</code>: you don&#39;t have to trust anyone; you can count.</p><p>Each fact is written as a tiny test that answers <strong>true or false</strong> by trying every case in a small, finite world. If it&#39;s true for every case, it holds. If not, it falls. That&#39;s the whole idea.</p><h2 id="_2-how-theorems-fold-into-each-other" tabindex="-1">2. How theorems fold into each other <a class="header-anchor" href="#_2-how-theorems-fold-into-each-other" aria-label="Permalink to “2. How theorems fold into each other”">​</a></h2><p><strong>Folding</strong> means small things join into one bigger thing, and the bigger thing still fits the same pattern.</p><ul><li>Facts come in groups of <strong>eight</strong> — an <strong>octave</strong>, like the eight steps of a musical scale before the tune repeats one octave higher.</li><li>Eight octaves <strong>fold</strong> into one seal; those seals fold again — many become <strong>one address</strong> you can check.</li><li>The proportions that show up are the ones you already see in the world: the <strong>golden ratio</strong> in a sunflower&#39;s seeds and a snail&#39;s shell, the <strong>Fibonacci</strong> counts in petals and pinecones, the <strong>doubling</strong> of an octave (double the frequency, one octave up), and <strong>DNA&#39;s</strong> four letters in three-letter words — <code>4 × 4 × 4 = 64</code>, the same 64 that keeps coming back.</li></ul><p>So the pattern in a shell, in a song, and in a strand of DNA is the <strong>same folding</strong> — small parts joining in steady proportion into a whole. You can recognise it in nature and live it in a day: rest, effort, rest.</p><h2 id="_3-how-a-problem-is-searched-researched-and-analysed" tabindex="-1">3. How a problem is searched, researched, and analysed <a class="header-anchor" href="#_3-how-a-problem-is-searched-researched-and-analysed" aria-label="Permalink to “3. How a problem is searched, researched, and analysed”">​</a></h2><p>When people write down a hard problem, here is the honest, repeatable way it is studied — with <strong>statistics</strong>, <strong>analytics</strong>, and <strong>forensics</strong>:</p><ol><li><strong>Search</strong> — look at what is already known and where the record is <strong>thin</strong>. The <a href="/millennium-solutions/WORKFLOWS.html">forensics</a> name the <em>exact</em> gap (a missing step in a family), not a vague &quot;somewhere around here&quot;.</li><li><strong>Research</strong> — try a small, decidable version you can actually check. Write it as a test over a finite world.</li><li><strong>Analyse</strong> — run it over <strong>every</strong> case (that&#39;s the statistics: not a sample, the whole set), fold the results, and check the <strong>chain</strong> so nothing was quietly changed (that&#39;s the forensics — a tamper shows up as a broken link, pointing to the exact spot).</li></ol><p>If the little fact holds and says something honest, it is <strong>kept and shared freely</strong>. If it over-claims, the gate <strong>drains</strong> it and shows the exact words to fix. Nothing is believed; everything is re-checked.</p><h2 id="_4-do-it-yourself-—-step-by-step-reproducible" tabindex="-1">4. Do it yourself — step by step (reproducible) <a class="header-anchor" href="#_4-do-it-yourself-—-step-by-step-reproducible" aria-label="Permalink to “4. Do it yourself — step by step (reproducible)”">​</a></h2><ol><li><strong>Draft</strong> a fact as a test that returns true or false over a finite set.</li><li><strong>Check it green</strong> — the test is true, its name makes no over-claim, and it isn&#39;t already recorded.</li><li><strong>Seal</strong> it — it gets a content-address (a fingerprint) and joins the chain.</li><li><strong>Share</strong> it — free for anyone to re-check.</li></ol><p>Try the live version on the <a href="/millennium-solutions/harness.html">harness</a>: type any sentence and watch the theorems compute the verdict, the address, and the honest form. Browse every fact on <a href="/millennium-solutions/organism.html">the organism</a>, or run the tools on the <a href="/millennium-solutions/examples.html">examples</a> page.</p><h2 id="_5-why-it-matters-—-a-harmonic-society" tabindex="-1">5. Why it matters — a harmonic society <a class="header-anchor" href="#_5-why-it-matters-—-a-harmonic-society" aria-label="Permalink to “5. Why it matters — a harmonic society”">​</a></h2><p>Every checked fact, freely shared, is a small <strong>contribution</strong> anyone can build on without asking permission and without being misled. That is the quiet aim: a fair, checkable commons where a claim is worth exactly what its re-computation shows — no more, no less. Earned, not minted.</p>`,18)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};